def fuzzy_line_anchor_distance(candidate_line: int, expected_line: int, max_drift: int) -> float:
    drift = abs(int(candidate_line) - int(expected_line))
    limit = max(1, abs(int(max_drift)))
    if drift >= limit:
        return 0.0
    return 1.0 - drift / float(limit)

def context_budget_proportional_alloc(total_budget: int, item_weight: float, sum_weights: float, min_floor: int) -> int:
    budget = max(0, int(total_budget))
    floor_val = max(0, min(budget, int(min_floor)))
    w = max(0.0, float(item_weight))
    sw = max(w, float(sum_weights))
    if sw <= 0.0:
        return floor_val
    raw = int(round(budget * (w / sw)))
    return max(floor_val, min(budget, raw))

def circuit_breaker_next_state(current_state: int, consecutive_failures: int, failure_threshold: int, cooldown_elapsed: bool) -> int:
    state = max(0, min(2, int(current_state)))
    fails = max(0, int(consecutive_failures))
    thresh = max(1, int(failure_threshold))
    if state == 2:
        return 1 if cooldown_elapsed else 2
    if state == 1:
        return 2 if fails > 0 else 0
    return 2 if fails >= thresh else 0

def critical_path_duration(stage_max_durations: list[float], overhead_per_stage: float) -> float:
    ov = max(0.0, float(overhead_per_stage))
    pos = [max(0.0, float(d)) for d in stage_max_durations]
    if not pos:
        return 0.0
    return sum(pos) + len(pos) * ov
